-- MES-7b-2 close-out, step 1.2 — F16 exposure, read-only (BEGIN READ ONLY … ROLLBACK; no temp objects — CREATE is refused in a read-only transaction).
-- Identity: postgres (rolbypassrls = true); change_log is a base table (relkind 'r'), so counts are real row counts.
-- The 45 views are the ones that ACCEPTED a zero-row write as anon and/or authenticated in MES-7b-2's before-measurement
-- (db/scripts/2026-10-16-mes7b2-view-writes.mjs, 2026-10-16 17:22 CST; log lines "VW|<view>|<kind>|<role>|<op>|ACCEPTED").
-- Base tables: walk each view's rewrite rule through pg_depend, recursively through views, keep relkind 'r' (a superset of the one
-- table a simple view's write lands on — reported so, never narrowed).
-- Run: psql "<pooler dsn>" -X -At -v ON_ERROR_STOP=1 -f docs/surveys/MES-8/f16-exposure.sql
BEGIN READ ONLY;
SELECT 'WHO|' || current_user || '|bypassrls=' || rolbypassrls FROM pg_roles WHERE rolname = current_user;
SELECT 'NOW|' || to_char(now() AT TIME ZONE 'Asia/Singapore', 'YYYY-MM-DD HH24:MI:SS') || ' CST';
WITH RECURSIVE dep(root, rel) AS (SELECT c.relname::text, c.oid FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public' WHERE c.relname = ANY (ARRAY['approval_log_masked','company_profile_masked','customer_billing_lookup','customer_credit_status','customer_lookup','electricity_allocation_reversals_masked','electricity_allocations_masked','employee_lookup','employees_masked','employment_history_masked','finance_settings_lookup','freight_document_lookup','gateway_keys_masked','handover_people','inbound_batch_lookup','inbound_batches_masked','journal_requests_masked','leave_requests_masked','medical_claims_masked','output_batch_lookup','output_batch_metal_lookup','payment_term_template_lines_masked','payroll_lines_masked','payroll_period_lookup','payroll_periods_masked','payroll_requests_masked','performance_reviews_masked','prepayment_applications_masked','price_history_masked','pricing_formula_history_masked','pricing_term_commitment_metals_masked','pricing_term_commitments_masked','processing_cost_entries_masked','processing_cost_entry_history_masked','processing_cost_entry_lookup','processing_output_lookup','processing_outputs_masked','processing_run_lookup','processing_runs_masked','purchase_order_history_masked','supplier_lookup','task_assignable_employees','tax_code_lookup','warehouse_requests_masked','work_order_lookup']::text[]) UNION SELECT dep.root, d.refobjid FROM dep JOIN pg_rewrite r ON r.ev_class = dep.rel JOIN pg_depend d ON d.classid = 'pg_rewrite'::regclass AND d.objid = r.oid AND d.refclassid = 'pg_class'::regclass AND d.refobjid <> dep.rel), f16_base AS (SELECT DISTINCT dep.root AS view_name, c.relname::text AS base_table FROM dep JOIN pg_class c ON c.oid = dep.rel AND c.relkind = 'r')
SELECT 'BASE|' || view_name || '|' || string_agg(base_table, ',' ORDER BY base_table) FROM f16_base GROUP BY view_name ORDER BY view_name;
WITH RECURSIVE dep(root, rel) AS (SELECT c.relname::text, c.oid FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public' WHERE c.relname = ANY (ARRAY['approval_log_masked','company_profile_masked','customer_billing_lookup','customer_credit_status','customer_lookup','electricity_allocation_reversals_masked','electricity_allocations_masked','employee_lookup','employees_masked','employment_history_masked','finance_settings_lookup','freight_document_lookup','gateway_keys_masked','handover_people','inbound_batch_lookup','inbound_batches_masked','journal_requests_masked','leave_requests_masked','medical_claims_masked','output_batch_lookup','output_batch_metal_lookup','payment_term_template_lines_masked','payroll_lines_masked','payroll_period_lookup','payroll_periods_masked','payroll_requests_masked','performance_reviews_masked','prepayment_applications_masked','price_history_masked','pricing_formula_history_masked','pricing_term_commitment_metals_masked','pricing_term_commitments_masked','processing_cost_entries_masked','processing_cost_entry_history_masked','processing_cost_entry_lookup','processing_output_lookup','processing_outputs_masked','processing_run_lookup','processing_runs_masked','purchase_order_history_masked','supplier_lookup','task_assignable_employees','tax_code_lookup','warehouse_requests_masked','work_order_lookup']::text[]) UNION SELECT dep.root, d.refobjid FROM dep JOIN pg_rewrite r ON r.ev_class = dep.rel JOIN pg_depend d ON d.classid = 'pg_rewrite'::regclass AND d.objid = r.oid AND d.refclassid = 'pg_class'::regclass AND d.refobjid <> dep.rel), f16_base AS (SELECT DISTINCT dep.root AS view_name, c.relname::text AS base_table FROM dep JOIN pg_class c ON c.oid = dep.rel AND c.relkind = 'r')
SELECT 'COUNTS|views=' || count(DISTINCT view_name) || '|base_tables=' || count(DISTINCT base_table) FROM f16_base;
SELECT 'CHANGELOG_RANGE|rows=' || count(*) || '|from=' || to_char(min(occurred_at) AT TIME ZONE 'Asia/Singapore', 'YYYY-MM-DD HH24:MI:SS')
    || '|to=' || to_char(max(occurred_at) AT TIME ZONE 'Asia/Singapore', 'YYYY-MM-DD HH24:MI:SS') || '|declared_began=' ||
    to_char(change_log_began_at() AT TIME ZONE 'Asia/Singapore', 'YYYY-MM-DD HH24:MI:SS') FROM change_log;
-- per base table: first captured row, and every write by actor class
WITH RECURSIVE dep(root, rel) AS (SELECT c.relname::text, c.oid FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public' WHERE c.relname = ANY (ARRAY['approval_log_masked','company_profile_masked','customer_billing_lookup','customer_credit_status','customer_lookup','electricity_allocation_reversals_masked','electricity_allocations_masked','employee_lookup','employees_masked','employment_history_masked','finance_settings_lookup','freight_document_lookup','gateway_keys_masked','handover_people','inbound_batch_lookup','inbound_batches_masked','journal_requests_masked','leave_requests_masked','medical_claims_masked','output_batch_lookup','output_batch_metal_lookup','payment_term_template_lines_masked','payroll_lines_masked','payroll_period_lookup','payroll_periods_masked','payroll_requests_masked','performance_reviews_masked','prepayment_applications_masked','price_history_masked','pricing_formula_history_masked','pricing_term_commitment_metals_masked','pricing_term_commitments_masked','processing_cost_entries_masked','processing_cost_entry_history_masked','processing_cost_entry_lookup','processing_output_lookup','processing_outputs_masked','processing_run_lookup','processing_runs_masked','purchase_order_history_masked','supplier_lookup','task_assignable_employees','tax_code_lookup','warehouse_requests_masked','work_order_lookup']::text[]) UNION SELECT dep.root, d.refobjid FROM dep JOIN pg_rewrite r ON r.ev_class = dep.rel JOIN pg_depend d ON d.classid = 'pg_rewrite'::regclass AND d.objid = r.oid AND d.refclassid = 'pg_class'::regclass AND d.refobjid <> dep.rel), f16_base AS (SELECT DISTINCT dep.root AS view_name, c.relname::text AS base_table FROM dep JOIN pg_class c ON c.oid = dep.rel AND c.relkind = 'r')
SELECT 'TBL|' || t.base_table || '|first=' || COALESCE(to_char(min(cl.occurred_at) AT TIME ZONE 'Asia/Singapore', 'YYYY-MM-DD HH24:MI'), '-')
    || '|rows=' || count(cl.seq)
    || '|user_authenticated=' || count(cl.seq) FILTER (WHERE cl.actor_kind = 'user' AND cl.db_role = 'authenticated')
    || '|anon=' || count(cl.seq) FILTER (WHERE cl.db_role = 'anon')
    || '|no_session=' || count(cl.seq) FILTER (WHERE cl.actor_kind = 'no_session')
    || '|other=' || count(cl.seq) FILTER (WHERE NOT (cl.actor_kind = 'user' AND cl.db_role = 'authenticated') AND cl.db_role <> 'anon' AND cl.actor_kind <> 'no_session')
  FROM (SELECT DISTINCT base_table FROM f16_base) t LEFT JOIN change_log cl ON cl.table_name = t.base_table
 GROUP BY t.base_table ORDER BY t.base_table;
-- every (actor_kind, db_role) pair seen on those tables
WITH RECURSIVE dep(root, rel) AS (SELECT c.relname::text, c.oid FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public' WHERE c.relname = ANY (ARRAY['approval_log_masked','company_profile_masked','customer_billing_lookup','customer_credit_status','customer_lookup','electricity_allocation_reversals_masked','electricity_allocations_masked','employee_lookup','employees_masked','employment_history_masked','finance_settings_lookup','freight_document_lookup','gateway_keys_masked','handover_people','inbound_batch_lookup','inbound_batches_masked','journal_requests_masked','leave_requests_masked','medical_claims_masked','output_batch_lookup','output_batch_metal_lookup','payment_term_template_lines_masked','payroll_lines_masked','payroll_period_lookup','payroll_periods_masked','payroll_requests_masked','performance_reviews_masked','prepayment_applications_masked','price_history_masked','pricing_formula_history_masked','pricing_term_commitment_metals_masked','pricing_term_commitments_masked','processing_cost_entries_masked','processing_cost_entry_history_masked','processing_cost_entry_lookup','processing_output_lookup','processing_outputs_masked','processing_run_lookup','processing_runs_masked','purchase_order_history_masked','supplier_lookup','task_assignable_employees','tax_code_lookup','warehouse_requests_masked','work_order_lookup']::text[]) UNION SELECT dep.root, d.refobjid FROM dep JOIN pg_rewrite r ON r.ev_class = dep.rel JOIN pg_depend d ON d.classid = 'pg_rewrite'::regclass AND d.objid = r.oid AND d.refclassid = 'pg_class'::regclass AND d.refobjid <> dep.rel), f16_base AS (SELECT DISTINCT dep.root AS view_name, c.relname::text AS base_table FROM dep JOIN pg_class c ON c.oid = dep.rel AND c.relkind = 'r')
SELECT 'ROLES|' || cl.actor_kind || '|' || cl.db_role || '|' || count(*) FROM change_log cl
 WHERE cl.table_name IN (SELECT base_table FROM f16_base) GROUP BY cl.actor_kind, cl.db_role ORDER BY 1;
ROLLBACK;
